import { connectToController, installConnectedController } from "./local-flash.mjs";

// AI: below section was generated by an AI
const $ = (selector) => document.querySelector(selector);
const ui = { connect:$("#connect"), install:$("#install"), confirmation:$("#physicalConfirmation"), confirmed:$("#confirmedDig2Go"), state:$("#controllerState"), status:$("#controllerStatus"), title:$("#installTitle"), instruction:$("#instruction"), note:$("#actionNote"), details:$("#technicalDetails"), result:$("#resultPanel"), resultTitle:$("#resultTitle"), resultMessage:$("#resultMessage") };
let selection = null;

function fact(term, value) { const row=document.createElement("div"); const dt=document.createElement("dt"); dt.textContent=term; const dd=document.createElement("dd"); dd.textContent=String(value); row.append(dt,dd); return row; }
function showFacts(records) { ui.details.replaceChildren(...records.map(([term,value]) => fact(term,value))); }
function setStatus(message, kind="") { ui.status.textContent=message; ui.state.className=`controller-state ${kind}`.trim(); }
function installAllowed() { return Boolean(selection && (selection.evidence.exactBoard || ui.confirmed.checked)); }
function syncInstall() { ui.install.disabled=!installAllowed(); }

async function loadCanonicalSelection() {
	const response=await fetch("/api/firmware-manifest");
	if (!response.ok) throw new Error("The bundled firmware is unavailable. Reinstall Easy Flash and try again.");
	const manifest=await response.json();
	if (manifest.variants.length !== 1) throw new Error("Easy Flash could not choose one supported controller firmware.");
	const variant=manifest.variants[0]; const artifact=variant.artifacts.find(({transport}) => transport === "usb");
	if (!artifact) throw new Error("The Dig2Go USB recovery firmware is missing.");
	return { variant,artifact };
}

async function connect() {
	ui.connect.disabled=true; ui.install.hidden=true; ui.confirmation.hidden=true; ui.note.hidden=true; ui.confirmed.checked=false; ui.result.hidden=true; selection=null; setStatus("Opening the USB controller chooser…");
	try {
		const canonical=await loadCanonicalSelection();
		const evidence=await connectToController({ variant:canonical.variant,onStatus:setStatus });
		selection={ ...canonical,evidence }; ui.title.textContent="Controller detected"; ui.instruction.textContent="Easy Flash found a compatible ESP32 and selected the Dig2Go firmware for you.";
		setStatus(`${evidence.chipName} detected. Check the printed controller label once before installing.`,"detected");
		showFacts([["Detected chip",evidence.chipName],["USB",`${evidence.portInfo.usbVendorId || "VID unavailable"} · ${evidence.portInfo.usbProductId || "PID unavailable"}`],["Board proof",evidence.exactBoard ? "Automatically matched" : "Chip only — printed label required"],["Firmware",canonical.variant.label],["Backup","Unavailable in browser USB mode"],["Install","Not started"]]);
		ui.confirmation.hidden=evidence.exactBoard; ui.install.hidden=false; ui.note.hidden=false; syncInstall();
	} catch (error) {
		ui.title.textContent="Plug in your controller"; setStatus(error.name === "NotFoundError" ? "No controller was selected. Plug it in and choose Connect." : error.message,"error");
	} finally { ui.connect.disabled=false; ui.connect.textContent=selection ? "Connect a different controller" : "Connect"; }
}

async function install() {
	if (!installAllowed()) return;
	ui.install.disabled=true; ui.connect.disabled=true; ui.confirmed.disabled=true; ui.result.hidden=true;
	try {
		const result=await installConnectedController({ variant:selection.variant,artifact:selection.artifact,onStatus(message){setStatus(message,"detected");},onProgress(percent){ui.install.textContent=`Installing… ${percent}%`;} });
		ui.title.textContent="Firmware installed"; setStatus("The controller restarted. Automatic health proof is unavailable in USB mode.","detected");
		showFacts([["Detected chip",result.chipName],["Firmware hash",result.sha256],["Backup",result.backup],["Write/readback",result.readback],["Restart","Requested"],["Health",result.health]]);
		ui.resultTitle.textContent="Installed — check the lights"; ui.resultMessage.textContent="The firmware write was accepted and the controller restarted, but Easy Flash could not automatically prove that WLED finished booting. If the lights do not start, reconnect and try again."; ui.result.hidden=false; ui.install.hidden=true; ui.confirmation.hidden=true; ui.note.hidden=true; selection=null;
	} catch (error) { setStatus(`Install stopped: ${error.message}. Reconnect the controller and try again.`,"error"); ui.install.textContent="Install"; ui.connect.disabled=false; }
	finally { ui.confirmed.disabled=false; }
}

ui.confirmed.addEventListener("change",syncInstall); ui.connect.addEventListener("click",connect); ui.install.addEventListener("click",install);
loadCanonicalSelection().then(({variant,artifact}) => showFacts([["Firmware",variant.label],["Target",variant.target.board],["Artifact check",`SHA-256 ${artifact.sha256}`],["Install","Not started"]])).catch((error) => setStatus(error.message,"error"));
